import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BkRhkvTH.js";const p=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md","lastUpdated":1784213339000}'),d={name:"guide/overview.md"};function i(n,e,s,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>VaultGuard is a self-hosted, zero-knowledge password manager. It stores logins, secure notes, credit cards, identities, Wi-Fi credentials and passkeys in an encrypted vault, and gives you the same vault from five different front-ends:</p><table tabindex="0"><thead><tr><th>Front-end</th><th>Project</th><th>Platform</th></tr></thead><tbody><tr><td>🖥️ Desktop</td><td><code>VaultGuard.WPF</code></td><td>Windows 10/11</td></tr><tr><td>🌐 Web</td><td><code>VaultGuard.Web</code></td><td>Blazor Server</td></tr><tr><td>🔌 API</td><td><code>VaultGuard.API</code></td><td>ASP.NET Core</td></tr><tr><td>📱 Mobile</td><td><code>VaultGuard.App</code></td><td>.NET MAUI (Android / iOS / Windows)</td></tr><tr><td>🧩 Extension</td><td><code>VaultGuard.BrowserExtension</code></td><td>Chrome / Edge / Firefox</td></tr></tbody></table><p>All five sit on top of one shared core - models, data access, crypto and business logic - so behaviour (validation, encryption, permissions) is identical no matter which client you open.</p><h2 id="why-zero-knowledge" tabindex="-1">Why &quot;zero-knowledge&quot; <a class="header-anchor" href="#why-zero-knowledge" aria-label="Permalink to &quot;Why &quot;zero-knowledge&quot;&quot;">​</a></h2><p>Your master password is never sent to the server and never written to disk. It is used, in memory, only long enough to derive the keys that encrypt and decrypt your vault on your device. A stolen database, backup file, or intercepted API payload is ciphertext without it - see <a href="/PasswordManagerApp/guide/security">Security Model</a> for exactly how that&#39;s enforced.</p><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h2><ul><li><strong>Vault item</strong> - a single secret (login, card, note, ...), always owned by exactly one user.</li><li><strong>Type</strong> - what kind of item it is (<code>Login</code>, <code>CreditCard</code>, <code>SecureNote</code>, <code>WiFi</code>, <code>Passkey</code>, <code>CryptoWallet</code>, ...) - 24 types in total, each with its own typed fields.</li><li><strong>Collection / Category / Tag</strong> - three independent, orthogonal ways to organise items: a collection is a broad grouping (e.g. &quot;Work&quot;), a category narrows by kind (e.g. &quot;Logins&quot;), tags are free-form labels.</li><li><strong>Vault (container)</strong> - a higher-level grouping used for sharing and access control.</li><li><strong>API key</strong> - a credential a client (mobile app, browser extension, script) uses instead of a full login session; scoped to one user, shown once, stored hash-only.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/PasswordManagerApp/guide/architecture">Architecture</a> - how the projects fit together and the request/data flow.</li><li><a href="/PasswordManagerApp/guide/getting-started">Getting Started</a> - clone, configure and run everything locally.</li><li><a href="/PasswordManagerApp/guide/security">Security Model</a> - key derivation, encryption, and what&#39;s stored vs. never stored.</li><li><a href="/PasswordManagerApp/platforms/web">Platforms</a> - a tour of each client with real screenshots.</li><li><a href="/PasswordManagerApp/api/reference">API Reference</a> - endpoints, authentication, request/response shapes.</li></ul>',10)])])}const g=t(d,[["render",i]]);export{p as __pageData,g as default};
